/// <summary>
/// Contract class AVACRLProtractedDefaultContract
/// </summary>
[DataContractAttribute]
final class AVACRLProtractedDefaultContract
{
    AmountMST   Limit;
    Days        daysAfterDue;
    str         packedQuery;

}

Method.Source:
/// <summary>
/// parmPackedQuery method
/// </summary>
/// <param name = "_packedQuery">str</param>
/// <returns>str</returns>
[
DataMemberAttribute,
AifQueryTypeAttribute('_packedQuery', queryStr(AVACRLReportResultProtractedQuery))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// parm method for Limit amount
/// </summary>
/// <param name = "_limit">AmountMST</param>
/// <returns>AmountMST</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@NDX:NXACRLMinAmount")),
    SysOperationHelpTextAttribute(literalStr("@NDX:NXACRLMinAmountHT")),
    SysOperationDisplayOrderAttribute('1')
]
public AmountMST parmLimit(AmountMST _limit = Limit)
{
    Limit = _limit;

    return Limit;
}

/// <summary>
/// parm method for after Due days
/// </summary>
/// <param name = "_days">Days</param>
/// <returns>Days</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@NDX:NXACRLDaysAfterDue")),
    SysOperationDisplayOrderAttribute('2')
]
public Days parmDaysAfterDue(Days _days = daysAfterdue)
{
    daysAfterDue = _days;

    return daysAfterDue;
}
